export const BRAIN_POINT_COUNT = 5760;

function fromB64(src: string): Uint8Array {
  const bin = atob(src);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

export function decodeBrainPoints(): Float32Array {
  const q = new Int16Array(fromB64(B64).buffer);
  const out = new Float32Array(q.length);
  for (let i = 0; i < q.length; i++) out[i] = q[i] / 8000;
  return out;
}

/** fold ∈ [0..1]: 1 — гребень извилины, 0 — дно борозды */
export function decodeBrainFold(): Float32Array {
  const b = fromB64(FOLD_B64);
  const out = new Float32Array(b.length);
  for (let i = 0; i < b.length; i++) out[i] = b[i] / 255;
  return out;
}
